


export type DeliveryPickupAvailabilityDiagnosticInput = { /** Stable reason a configured pickup location was left out of the results or cannot supply the order. - `pickup_location_inactive`: The Location is inactive, so it was left out. - `pickup_location_geography_unavailable`: The Location has no usable published geography, so it was left out. - `pickup_location_inventory_unavailable`: The Location does not allocate inventory, so it cannot supply the order's tracked items. It is listed with an unavailable outcome. Items without tracked inventory need no allocation. - `pickup_location_dependency_failure`: Flint could not resolve the configured Location. */ "code": "pickup_location_inactive" | "pickup_location_geography_unavailable" | "pickup_location_inventory_unavailable" | "pickup_location_dependency_failure"; "diagnostic_id": string; "location_id": string; /** RFC3339 timestamp. Format: date-time. */ "occurred_at": string | globalThis.Date; "outcome": "unavailable" | "cannot_calculate"; "recommended_action": "review_configuration" | "retry"; "retryable": boolean; "scope": "location"; "summary": string; };
